  add("trigonometry", "tr2", 2, [{"type":"regular","q":"From a point 50 m away, the angle of elevation to a building is 35°. What is the height? (Use \\(\\tan 35° \\approx 0.700\\).)","answer":"\\(\\approx 35\\) m","solution":"Height = distance × \\(\\tan\\theta = 50 × 0.700\\)."},{"type":"regular","q":"A ladder 15 ft long leans against a wall at a 60° angle with the ground. How high does it reach?","answer":"\\(\\frac{15\\sqrt{3}}{2} \\approx 13.0\\) ft","solution":"Height = hypotenuse × \\(\\sin 60° = 15 × \\frac{\\sqrt{3}}{2}\\)."},{"type":"regular","q":"From 120 m away, the angle of elevation to a tower is 40°. What is the tower's height? (Use \\(\\tan 40° \\approx 0.839\\).)","answer":"\\(\\approx 100.7\\) m","solution":"Height = 120 × \\(\\tan 40°\\)."},{"type":"regular","q":"A 20 ft ladder leans against a wall. If the base is 12 ft from the wall, what is the angle of elevation?","answer":"\\(\\approx 53.1°\\)","solution":"\\(\\cos\\theta = \\frac{12}{20} = 0.6\\); \\(\\theta = \\arccos(0.6) \\approx 53.1°\\)."},{"type":"regular","q":"A ramp rises 3 m over a horizontal distance of 12 m. What is the angle of inclination?","answer":"\\(\\approx 14.0°\\)","solution":"\\(\\tan\\theta = \\frac{3}{12} = 0.25\\); \\(\\theta = \\arctan(0.25) \\approx 14.0°\\)."},{"type":"word","q":"A tree casts a shadow 25 m long. The angle of elevation of the sun is 35°. How tall is the tree? (Use \\(\\tan 35° \\approx 0.700\\).)","answer":"\\(\\approx 17.5\\) m","solution":"Height = shadow length × \\(\\tan\\theta\\)."},{"type":"word","q":"From a window 30 m above the ground, the angle of depression to a car is 25°. How far is the car from the base of the building? (Use \\(\\tan 25° \\approx 0.466\\).)","answer":"\\(\\approx 64.4\\) m","solution":"Distance = height ÷ \\(\\tan\\theta = 30 ÷ 0.466\\)."},{"type":"word","q":"A person 6 ft tall stands 40 ft from a building. The angle of elevation from the person's eyes to the top is 25°. How tall is the building? (Use \\(\\tan 25° \\approx 0.466\\).)","answer":"\\(\\approx 24.6\\) ft","solution":"Height above eye level = 40 × \\(\\tan 25°\\); total height ≈ 24.6 + 6 ft."},{"type":"word","q":"A plane flying at 2000 m altitude is 5000 m away (horizontally) from an airport. What is the angle of depression to the airport?","answer":"\\(\\approx 21.8°\\)","solution":"\\(\\tan\\theta = \\frac{2000}{5000} = 0.4\\); \\(\\theta = \\arctan(0.4) \\approx 21.8°\\)."},{"type":"word","q":"Two buildings are 100 m apart. From the top of the first (height 50 m), the angle of depression to the top of the second is 15°. What is the height of the second building? (Use \\(\\tan 15° \\approx 0.268\\).)","answer":"\\(\\approx 23.2\\) m","solution":"Drop = 100 × \\(\\tan 15° \\approx 26.8\\) m; second building height ≈ 50 − 26.8 m."},{"type":"word","q":"A surveyor measures a hill. From point A, the angle of elevation to the summit is 20°. After moving 200 m closer (horizontally), the angle is 30°. Estimate the height. (Use \\(\\tan 20° \\approx 0.364\\), \\(\\tan 30° \\approx 0.577\\).)","answer":"\\(\\approx 115.4\\) m","solution":"Set up equations: \\(h = d \\tan 20° = (d-200) \\tan 30°\\); solve for \\(d\\) and \\(h\\)."},{"type":"word","q":"A boat is 400 m from a lighthouse. The angle of elevation from the boat to the top is 12°. How tall is the lighthouse? (Use \\(\\tan 12° \\approx 0.213\\).)","answer":"\\(\\approx 85.2\\) m","solution":"Height = 400 × \\(\\tan 12°\\)."},{"type":"word","q":"A kite string is 50 m long and makes a 50° angle with the ground. How high is the kite? (Use \\(\\sin 50° \\approx 0.766\\).)","answer":"\\(\\approx 38.3\\) m","solution":"Height = string length × \\(\\sin 50°\\)."},{"type":"word","q":"A ramp for wheelchair access rises 1.5 m over a length of 15 m. What is the angle of inclination?","answer":"\\(\\approx 5.7°\\)","solution":"\\(\\sin\\theta = \\frac{1.5}{15} = 0.1\\); \\(\\theta = \\arcsin(0.1) \\approx 5.7°\\)."},{"type":"word","q":"From a cliff 80 m high, the angle of depression to a boat is 35°. How far is the boat from the base of the cliff? (Use \\(\\tan 35° \\approx 0.700\\).)","answer":"\\(\\approx 114.3\\) m","solution":"Distance = height ÷ \\(\\tan 35°\\)."}]);
  addCum("trigonometry", "tr2", [{"type":"regular","q":"In a right triangle, opposite = 11, hypotenuse = 61. Find \\(\\sin\\theta\\).","answer":"\\(\\frac{11}{61}\\)","solution":"Sine is opposite over hypotenuse."},{"type":"regular","q":"Find \\(\\cos 30°\\).","answer":"\\(\\frac{\\sqrt{3}}{2}\\)","solution":"30-60-90 triangle: \\(\\cos 30° = \\frac{\\sqrt{3}}{2}\\)."},{"type":"regular","q":"Find \\(\\sin 45°\\).","answer":"\\(\\frac{\\sqrt{2}}{2}\\)","solution":"45-45-90 triangle: \\(\\sin 45° = \\frac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"If \\(\\sin\\theta = \\frac{9}{41}\\) (QI), find \\(\\cos\\theta\\).","answer":"\\(\\frac{40}{41}\\)","solution":"Use \\(\\cos^2\\theta = 1 - \\sin^2\\theta = 1 - \\frac{81}{1681} = \\frac{1600}{1681}\\)."},{"type":"regular","q":"In a 30-60-90 triangle with short leg 7, find the hypotenuse.","answer":"14","solution":"Hypotenuse = 2 × short leg."},{"type":"regular","q":"A right triangle has legs 5 and 12. Find \\(\\tan\\theta\\) where \\(\\theta\\) is opposite the leg of length 5.","answer":"\\(\\frac{5}{12}\\)","solution":"Tangent is opposite over adjacent."},{"type":"regular","q":"Find \\(\\tan 30°\\).","answer":"\\(\\frac{\\sqrt{3}}{3}\\)","solution":"30-60-90 triangle: \\(\\tan 30° = \\frac{1}{\\sqrt{3}} = \\frac{\\sqrt{3}}{3}\\)."},{"type":"regular","q":"In a 45-45-90 triangle with hypotenuse 10, find each leg.","answer":"\\(5\\sqrt{2}\\)","solution":"Leg = hypotenuse ÷ \\(\\sqrt{2}\\)."},{"type":"regular","q":"If \\(\\tan\\theta = \\frac{8}{15}\\) (QI), find \\(\\sin\\theta\\).","answer":"\\(\\frac{8}{17}\\)","solution":"Hypotenuse is \\(\\sqrt{64+225} = 17\\); \\(\\sin\\theta = \\frac{8}{17}\\)."},{"type":"regular","q":"Find \\(\\cos 60°\\).","answer":"\\(\\frac{1}{2}\\)","solution":"30-60-90 triangle: \\(\\cos 60° = \\frac{1}{2}\\)."},{"type":"regular","q":"In a 30-60-90 triangle with hypotenuse 18, find the long leg.","answer":"\\(9\\sqrt{3}\\)","solution":"Long leg = hypotenuse × \\(\\sin 60° = 18 × \\frac{\\sqrt{3}}{2}\\)."},{"type":"regular","q":"A right triangle has hypotenuse 29 and one leg 20. Find \\(\\cos\\theta\\) where \\(\\theta\\) is opposite the leg of length 20.","answer":"\\(\\frac{21}{29}\\)","solution":"Other leg is \\(\\sqrt{841-400} = 21\\); \\(\\cos\\theta\\) is adjacent over hypotenuse."},{"type":"word","q":"A ladder 13 m long leans against a wall and reaches 12 m high. What is \\(\\sin\\theta\\) where \\(\\theta\\) is the angle between the ladder and the wall?","answer":"\\(\\frac{5}{13}\\)","solution":"Base distance is \\(\\sqrt{169-144} = 5\\) m; \\(\\sin\\theta = \\frac{5}{13}\\)."},{"type":"word","q":"From 60 m away, the angle of elevation to a flagpole is 50°. How tall is the flagpole? (Use \\(\\tan 50° \\approx 1.192\\).)","answer":"\\(\\approx 71.5\\) m","solution":"Height = 60 × \\(\\tan 50°\\)."},{"type":"word","q":"A square has diagonal 14. What is the side length?","answer":"\\(7\\sqrt{2}\\)","solution":"Side = diagonal ÷ \\(\\sqrt{2} = 14 ÷ \\sqrt{2} = 7\\sqrt{2}\\)."},{"type":"word","q":"From a window 45 m above ground, the angle of depression to a car is 30°. How far is the car from the building? (Use \\(\\tan 30° \\approx 0.577\\).)","answer":"\\(\\approx 77.9\\) m","solution":"Distance = height ÷ \\(\\tan 30°\\)."},{"type":"word","q":"A ramp rises 2 m over 10 m of horizontal distance. What is the angle of inclination?","answer":"\\(\\approx 11.3°\\)","solution":"\\(\\tan\\theta = \\frac{2}{10} = 0.2\\); \\(\\theta = \\arctan(0.2) \\approx 11.3°\\)."},{"type":"word","q":"A tree casts a 30 m shadow when the sun's angle of elevation is 40°. How tall is the tree? (Use \\(\\tan 40° \\approx 0.839\\).)","answer":"\\(\\approx 25.2\\) m","solution":"Height = shadow × \\(\\tan 40°\\)."},{"type":"word","q":"A 30-60-90 triangle has hypotenuse 24. What is the short leg?","answer":"12","solution":"Short leg = hypotenuse ÷ 2."},{"type":"word","q":"From point A, the angle of elevation to a tower is 25°. From 100 m closer (point B), the angle is 40°. Estimate the tower height. (Use \\(\\tan 25° \\approx 0.466\\), \\(\\tan 40° \\approx 0.839\\).)","answer":"\\(\\approx 63.8\\) m","solution":"Set up: \\(h = d \\tan 25° = (d-100) \\tan 40°\\); solve for \\(h\\)."},{"type":"word","q":"A kite string is 40 m long and makes a 55° angle with the ground. How high is the kite? (Use \\(\\sin 55° \\approx 0.819\\).)","answer":"\\(\\approx 32.8\\) m","solution":"Height = string length × \\(\\sin 55°\\)."},{"type":"word","q":"A right triangle has legs 7 and 24. What is \\(\\sin\\theta\\) where \\(\\theta\\) is opposite the leg of length 7?","answer":"\\(\\frac{7}{25}\\)","solution":"Hypotenuse is \\(\\sqrt{49+576} = 25\\); \\(\\sin\\theta = \\frac{7}{25}\\)."},{"type":"word","q":"An equilateral triangle has side 12. What is its height?","answer":"\\(6\\sqrt{3}\\)","solution":"Height = \\(\\frac{\\sqrt{3}}{2} \\times 12 = 6\\sqrt{3}\\)."},{"type":"word","q":"From a cliff 100 m high, the angle of depression to a boat is 20°. How far is the boat from the cliff base? (Use \\(\\tan 20° \\approx 0.364\\).)","answer":"\\(\\approx 274.7\\) m","solution":"Distance = height ÷ \\(\\tan 20°\\)."}]);
  add("trigonometry", "tr3", 0, [{"type":"regular","q":"What is \\(\\sin\\dfrac{\\pi}{6}\\)?","answer":"\\(\\dfrac{1}{2}\\)","solution":"On the unit circle, the point at \\(\\dfrac{\\pi}{6}\\) has y-coordinate \\(\\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\cos\\dfrac{\\pi}{3}\\)?","answer":"\\(\\dfrac{1}{2}\\)","solution":"On the unit circle, the point at \\(\\dfrac{\\pi}{3}\\) has x-coordinate \\(\\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\sin\\dfrac{3\\pi}{2}\\)?","answer":"\\(-1\\)","solution":"At \\(\\dfrac{3\\pi}{2}\\) (bottom of circle), the y-coordinate is \\(-1\\)."},{"type":"regular","q":"What is \\(\\cos\\dfrac{\\pi}{4}\\)?","answer":"\\(\\dfrac{\\sqrt{2}}{2}\\)","solution":"At \\(\\dfrac{\\pi}{4}\\), both coordinates equal \\(\\dfrac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"What is \\(\\sin\\dfrac{7\\pi}{6}\\)?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"\\(\\dfrac{7\\pi}{6}\\) is in QIII with reference angle \\(\\dfrac{\\pi}{6}\\), so \\(\\sin = -\\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\cos\\dfrac{3\\pi}{4}\\)?","answer":"\\(-\\dfrac{\\sqrt{2}}{2}\\)","solution":"\\(\\dfrac{3\\pi}{4}\\) is in QII with reference angle \\(\\dfrac{\\pi}{4}\\), so \\(\\cos = -\\dfrac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"What is \\(\\sin\\dfrac{11\\pi}{6}\\)?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"\\(\\dfrac{11\\pi}{6}\\) is in QIV with reference angle \\(\\dfrac{\\pi}{6}\\), so \\(\\sin = -\\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\cos0\\)?","answer":"\\(1\\)","solution":"At \\(0\\) (right side of circle), the x-coordinate is \\(1\\)."},{"type":"word","q":"A point on the unit circle has \\(\\sin\\theta = \\dfrac{\\sqrt{3}}{2}\\). What are the possible values of \\(\\theta\\) in \\([0, 2\\pi)\\)?","answer":"\\(\\dfrac{\\pi}{3}, \\dfrac{2\\pi}{3}\\)","solution":"\\(\\sin\\theta = \\dfrac{\\sqrt{3}}{2}\\) occurs at \\(\\dfrac{\\pi}{3}\\) in QI and \\(\\dfrac{2\\pi}{3}\\) in QII."},{"type":"word","q":"At what angle in \\([0, 2\\pi)\\) does \\(\\cos\\theta = -\\dfrac{1}{2}\\)?","answer":"\\(\\dfrac{2\\pi}{3}, \\dfrac{4\\pi}{3}\\)","solution":"\\(\\cos\\theta = -\\dfrac{1}{2}\\) in QII at \\(\\dfrac{2\\pi}{3}\\) and in QIII at \\(\\dfrac{4\\pi}{3}\\)."},{"type":"word","q":"Find all \\(\\theta\\) in \\([0, 2\\pi)\\) where \\(\\sin\\theta = \\cos\\theta\\).","answer":"\\(\\dfrac{\\pi}{4}, \\dfrac{5\\pi}{4}\\)","solution":"\\(\\sin\\theta = \\cos\\theta\\) when the reference angle is \\(\\dfrac{\\pi}{4}\\) in QI and QIII."},{"type":"word","q":"A Ferris wheel rotates through angle \\(\\dfrac{5\\pi}{4}\\). What is the sine of this angle?","answer":"\\(-\\dfrac{\\sqrt{2}}{2}\\)","solution":"\\(\\dfrac{5\\pi}{4}\\) is in QIII with reference angle \\(\\dfrac{\\pi}{4}\\), so \\(\\sin = -\\dfrac{\\sqrt{2}}{2}\\)."},{"type":"word","q":"In which quadrants is \\(\\cos\\theta\\) negative?","answer":"QII and QIII","solution":"Cosine (x-coordinate) is negative where x < 0, which is quadrants II and III."},{"type":"word","q":"What is the sine of the angle \\(\\dfrac{4\\pi}{3}\\)?","answer":"\\(-\\dfrac{\\sqrt{3}}{2}\\)","solution":"\\(\\dfrac{4\\pi}{3}\\) is in QIII with reference angle \\(\\dfrac{\\pi}{3}\\), so \\(\\sin = -\\dfrac{\\sqrt{3}}{2}\\)."}]);
  add("trigonometry", "tr3", 1, [{"type":"regular","q":"What is \\(\\sin 30°\\)?","answer":"\\(\\dfrac{1}{2}\\)","solution":"30° is a standard angle with \\(\\sin 30° = \\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\cos 45°\\)?","answer":"\\(\\dfrac{\\sqrt{2}}{2}\\)","solution":"45° is a standard angle with \\(\\cos 45° = \\dfrac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"What is \\(\\sin 210°\\)?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"210° is in QIII with reference angle 30°, so \\(\\sin 210° = -\\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\cos 120°\\)?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"120° is in QII with reference angle 60°, so \\(\\cos 120° = -\\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\tan 60°\\)?","answer":"\\(\\sqrt{3}\\)","solution":"60° is a standard angle with \\(\\tan 60° = \\dfrac{\\sin 60°}{\\cos 60°} = \\dfrac{\\sqrt{3}/2}{1/2} = \\sqrt{3}\\)."},{"type":"regular","q":"What is \\(\\sin 300°\\)?","answer":"\\(-\\dfrac{\\sqrt{3}}{2}\\)","solution":"300° is in QIV with reference angle 60°, so \\(\\sin 300° = -\\dfrac{\\sqrt{3}}{2}\\)."},{"type":"regular","q":"What is \\(\\cos 315°\\)?","answer":"\\(\\dfrac{\\sqrt{2}}{2}\\)","solution":"315° is in QIV with reference angle 45°, so \\(\\cos 315° = \\dfrac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"What is \\(\\tan 225°\\)?","answer":"\\(1\\)","solution":"225° is in QIII with reference angle 45°; both sin and cos are negative, so \\(\\tan 225° = 1\\)."},{"type":"word","q":"If \\(\\sin\\theta = \\dfrac{\\sqrt{3}}{2}\\) and \\(\\theta\\) is in QII, what is \\(\\cos\\theta\\)?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"In QII with \\(\\sin\\theta = \\dfrac{\\sqrt{3}}{2}\\), the reference angle is 60°, so \\(\\cos\\theta = -\\dfrac{1}{2}\\)."},{"type":"word","q":"An angle measures 330°. What is its tangent?","answer":"\\(-\\dfrac{\\sqrt{3}}{3}\\) or \\(-\\dfrac{1}{\\sqrt{3}}\\)","solution":"330° is in QIV with reference angle 30°; \\(\\tan 330° = -\\tan 30° = -\\dfrac{\\sqrt{3}}{3}\\)."},{"type":"word","q":"If \\(\\cos\\theta = -\\dfrac{\\sqrt{2}}{2}\\) and \\(\\theta\\) is in QIII, what is \\(\\sin\\theta\\)?","answer":"\\(-\\dfrac{\\sqrt{2}}{2}\\)","solution":"In QIII with \\(\\cos\\theta = -\\dfrac{\\sqrt{2}}{2}\\), the reference angle is 45°, so \\(\\sin\\theta = -\\dfrac{\\sqrt{2}}{2}\\)."},{"type":"word","q":"A surveyor measures an angle of 120°. What is the cosine of this angle?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"120° is in QII with reference angle 60°, so \\(\\cos 120° = -\\dfrac{1}{2}\\)."},{"type":"word","q":"In which quadrant is \\(\\theta\\) if \\(\\sin\\theta > 0\\) and \\(\\cos\\theta < 0\\)?","answer":"QII","solution":"Sine is positive and cosine is negative only in quadrant II."},{"type":"word","q":"What is \\(\\sin 270°\\)?","answer":"\\(-1\\)","solution":"270° corresponds to the bottom of the unit circle where \\(\\sin 270° = -1\\)."},{"type":"word","q":"If \\(\\tan\\theta = -1\\) and \\(\\theta\\) is in QIV, what is \\(\\theta\\) in degrees (in \\([0°, 360°)\\))?","answer":"\\(315°\\)","solution":"\\(\\tan\\theta = -1\\) with reference angle 45° in QIV gives \\(\\theta = 315°\\)."}]);
  add("trigonometry", "tr3", 2, [{"type":"regular","q":"What is \\(\\csc 45°\\)?","answer":"\\(\\sqrt{2}\\)","solution":"\\(\\csc 45° = \\dfrac{1}{\\sin 45°} = \\dfrac{1}{\\sqrt{2}/2} = \\sqrt{2}\\)."},{"type":"regular","q":"What is \\(\\sec 30°\\)?","answer":"\\(\\dfrac{2\\sqrt{3}}{3}\\)","solution":"\\(\\sec 30° = \\dfrac{1}{\\cos 30°} = \\dfrac{1}{\\sqrt{3}/2} = \\dfrac{2\\sqrt{3}}{3}\\)."},{"type":"regular","q":"What is \\(\\cot 60°\\)?","answer":"\\(\\dfrac{\\sqrt{3}}{3}\\)","solution":"\\(\\cot 60° = \\dfrac{1}{\\tan 60°} = \\dfrac{1}{\\sqrt{3}} = \\dfrac{\\sqrt{3}}{3}\\)."},{"type":"regular","q":"If \\(\\cos\\theta = \\dfrac{2}{5}\\), what is \\(\\sec\\theta\\)?","answer":"\\(\\dfrac{5}{2}\\)","solution":"\\(\\sec\\theta = \\dfrac{1}{\\cos\\theta} = \\dfrac{1}{2/5} = \\dfrac{5}{2}\\)."},{"type":"regular","q":"What is \\(\\csc 60°\\)?","answer":"\\(\\dfrac{2\\sqrt{3}}{3}\\)","solution":"\\(\\csc 60° = \\dfrac{1}{\\sin 60°} = \\dfrac{1}{\\sqrt{3}/2} = \\dfrac{2\\sqrt{3}}{3}\\)."},{"type":"regular","q":"What is \\(\\sec 45°\\)?","answer":"\\(\\sqrt{2}\\)","solution":"\\(\\sec 45° = \\dfrac{1}{\\cos 45°} = \\dfrac{1}{\\sqrt{2}/2} = \\sqrt{2}\\)."},{"type":"regular","q":"If \\(\\tan\\theta = \\dfrac{3}{4}\\), what is \\(\\cot\\theta\\)?","answer":"\\(\\dfrac{4}{3}\\)","solution":"\\(\\cot\\theta = \\dfrac{1}{\\tan\\theta} = \\dfrac{1}{3/4} = \\dfrac{4}{3}\\)."},{"type":"regular","q":"What is \\(\\cot 30°\\)?","answer":"\\(\\sqrt{3}\\)","solution":"\\(\\cot 30° = \\dfrac{1}{\\tan 30°} = \\dfrac{1}{1/\\sqrt{3}} = \\sqrt{3}\\)."},{"type":"word","q":"If \\(\\sin\\theta = \\dfrac{5}{13}\\), what is \\(\\csc\\theta\\)?","answer":"\\(\\dfrac{13}{5}\\)","solution":"\\(\\csc\\theta = \\dfrac{1}{\\sin\\theta} = \\dfrac{1}{5/13} = \\dfrac{13}{5}\\)."},{"type":"word","q":"A right triangle has adjacent side 7 and hypotenuse 10. What is the secant of the angle?","answer":"\\(\\dfrac{10}{7}\\)","solution":"\\(\\sec\\theta = \\dfrac{\\text{hypotenuse}}{\\text{adjacent}} = \\dfrac{10}{7}\\)."},{"type":"word","q":"If \\(\\cot\\theta = 2\\), what is \\(\\tan\\theta\\)?","answer":"\\(\\dfrac{1}{2}\\)","solution":"\\(\\tan\\theta = \\dfrac{1}{\\cot\\theta} = \\dfrac{1}{2}\\)."},{"type":"word","q":"In a right triangle, the opposite side is 8 and the hypotenuse is 17. What is the cosecant?","answer":"\\(\\dfrac{17}{8}\\)","solution":"\\(\\csc\\theta = \\dfrac{\\text{hypotenuse}}{\\text{opposite}} = \\dfrac{17}{8}\\)."},{"type":"word","q":"What is \\(\\sec 0°\\)?","answer":"\\(1\\)","solution":"\\(\\sec 0° = \\dfrac{1}{\\cos 0°} = \\dfrac{1}{1} = 1\\)."},{"type":"word","q":"If \\(\\csc\\theta = 3\\), what is \\(\\sin\\theta\\)?","answer":"\\(\\dfrac{1}{3}\\)","solution":"\\(\\sin\\theta = \\dfrac{1}{\\csc\\theta} = \\dfrac{1}{3}\\)."},{"type":"word","q":"What is \\(\\cot 90°\\)?","answer":"\\(0\\)","solution":"\\(\\cot 90° = \\dfrac{\\cos 90°}{\\sin 90°} = \\dfrac{0}{1} = 0\\)."}]);
  addCum("trigonometry", "tr3", [{"type":"regular","q":"What is \\(\\sin\\dfrac{\\pi}{3}\\)?","answer":"\\(\\dfrac{\\sqrt{3}}{2}\\)","solution":"At \\(\\dfrac{\\pi}{3}\\) on the unit circle, the y-coordinate is \\(\\dfrac{\\sqrt{3}}{2}\\)."},{"type":"regular","q":"What is \\(\\cos 60°\\)?","answer":"\\(\\dfrac{1}{2}\\)","solution":"60° is a standard angle with \\(\\cos 60° = \\dfrac{1}{2}\\)."},{"type":"regular","q":"What is \\(\\tan\\dfrac{\\pi}{3}\\)?","answer":"\\(\\sqrt{3}\\)","solution":"\\(\\tan\\dfrac{\\pi}{3} = \\dfrac{\\sin(\\pi/3)}{\\cos(\\pi/3)} = \\dfrac{\\sqrt{3}/2}{1/2} = \\sqrt{3}\\)."},{"type":"regular","q":"What is \\(\\csc\\dfrac{\\pi}{6}\\)?","answer":"\\(2\\)","solution":"\\(\\csc\\dfrac{\\pi}{6} = \\dfrac{1}{\\sin(\\pi/6)} = \\dfrac{1}{1/2} = 2\\)."},{"type":"regular","q":"What is \\(\\sec\\dfrac{\\pi}{3}\\)?","answer":"\\(2\\)","solution":"\\(\\sec\\dfrac{\\pi}{3} = \\dfrac{1}{\\cos(\\pi/3)} = \\dfrac{1}{1/2} = 2\\)."},{"type":"regular","q":"What is \\(\\sin 120°\\)?","answer":"\\(\\dfrac{\\sqrt{3}}{2}\\)","solution":"120° is in QII with reference angle 60°, so \\(\\sin 120° = \\dfrac{\\sqrt{3}}{2}\\)."},{"type":"regular","q":"What is \\(\\cos\\dfrac{5\\pi}{6}\\)?","answer":"\\(-\\dfrac{\\sqrt{3}}{2}\\)","solution":"\\(\\dfrac{5\\pi}{6}\\) is in QII with reference angle \\(\\dfrac{\\pi}{6}\\), so \\(\\cos = -\\dfrac{\\sqrt{3}}{2}\\)."},{"type":"regular","q":"What is \\(\\cot\\dfrac{\\pi}{4}\\)?","answer":"\\(1\\)","solution":"\\(\\cot\\dfrac{\\pi}{4} = \\dfrac{1}{\\tan(\\pi/4)} = \\dfrac{1}{1} = 1\\)."},{"type":"regular","q":"If \\(\\sin\\theta = -\\dfrac{\\sqrt{2}}{2}\\) and \\(\\theta\\) is in QIV, what is \\(\\cos\\theta\\)?","answer":"\\(\\dfrac{\\sqrt{2}}{2}\\)","solution":"In QIV with \\(\\sin\\theta = -\\dfrac{\\sqrt{2}}{2}\\), the reference angle is 45°, so \\(\\cos\\theta = \\dfrac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"What is \\(\\tan 90°\\)?","answer":"Undefined","solution":"\\(\\tan 90° = \\dfrac{\\sin 90°}{\\cos 90°} = \\dfrac{1}{0}\\), which is undefined."},{"type":"regular","q":"What is \\(\\csc 180°\\)?","answer":"Undefined","solution":"\\(\\csc 180° = \\dfrac{1}{\\sin 180°} = \\dfrac{1}{0}\\), which is undefined."},{"type":"regular","q":"What is \\(\\sin\\dfrac{5\\pi}{4}\\)?","answer":"\\(-\\dfrac{\\sqrt{2}}{2}\\)","solution":"\\(\\dfrac{5\\pi}{4}\\) is in QIII with reference angle \\(\\dfrac{\\pi}{4}\\), so \\(\\sin = -\\dfrac{\\sqrt{2}}{2}\\)."},{"type":"word","q":"A clock hand points at 210°. What is the sine of this angle?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"210° is in QIII with reference angle 30°, so \\(\\sin 210° = -\\dfrac{1}{2}\\)."},{"type":"word","q":"An angle has \\(\\cos\\theta = \\dfrac{3}{5}\\). What is \\(\\sec\\theta\\)?","answer":"\\(\\dfrac{5}{3}\\)","solution":"\\(\\sec\\theta = \\dfrac{1}{\\cos\\theta} = \\dfrac{1}{3/5} = \\dfrac{5}{3}\\)."},{"type":"word","q":"In which quadrants is \\(\\sin\\theta\\) negative?","answer":"QIII and QIV","solution":"Sine (y-coordinate) is negative where y < 0, which is quadrants III and IV."},{"type":"word","q":"If \\(\\tan\\theta = \\dfrac{1}{\\sqrt{3}}\\) and \\(\\theta\\) is acute, what is \\(\\theta\\) in degrees?","answer":"\\(30°\\)","solution":"\\(\\tan 30° = \\dfrac{1}{\\sqrt{3}}\\), so \\(\\theta = 30°\\)."},{"type":"word","q":"A rotating beam sweeps through \\(\\dfrac{7\\pi}{4}\\) radians. What is the cosine of this angle?","answer":"\\(\\dfrac{\\sqrt{2}}{2}\\)","solution":"\\(\\dfrac{7\\pi}{4}\\) is in QIV with reference angle \\(\\dfrac{\\pi}{4}\\), so \\(\\cos = \\dfrac{\\sqrt{2}}{2}\\)."},{"type":"word","q":"If \\(\\cot\\theta = \\dfrac{5}{12}\\), what is \\(\\tan\\theta\\)?","answer":"\\(\\dfrac{12}{5}\\)","solution":"\\(\\tan\\theta = \\dfrac{1}{\\cot\\theta} = \\dfrac{1}{5/12} = \\dfrac{12}{5}\\)."},{"type":"word","q":"What is \\(\\sin 360°\\)?","answer":"\\(0\\)","solution":"360° is a full rotation, equivalent to 0°, where \\(\\sin 360° = 0\\)."},{"type":"word","q":"An angle in standard position has terminal side in QII. Is \\(\\tan\\theta\\) positive or negative?","answer":"Negative","solution":"In QII, sine is positive and cosine is negative, so \\(\\tan\\theta = \\dfrac{\\sin}{\\cos}\\) is negative."},{"type":"word","q":"If \\(\\sin\\theta = \\dfrac{7}{25}\\), what is \\(\\csc\\theta\\)?","answer":"\\(\\dfrac{25}{7}\\)","solution":"\\(\\csc\\theta = \\dfrac{1}{\\sin\\theta} = \\dfrac{1}{7/25} = \\dfrac{25}{7}\\)."},{"type":"word","q":"What is \\(\\cot 180°\\)?","answer":"Undefined","solution":"\\(\\cot 180° = \\dfrac{\\cos 180°}{\\sin 180°} = \\dfrac{-1}{0}\\), which is undefined."},{"type":"word","q":"An angle measures \\(\\dfrac{3\\pi}{2}\\) radians. What is its tangent?","answer":"Undefined","solution":"At \\(\\dfrac{3\\pi}{2}\\), \\(\\sin = -1\\) and \\(\\cos = 0\\), so \\(\\tan\\) is undefined."},{"type":"word","q":"If \\(\\sec\\theta = -2\\) and \\(\\theta\\) is in QII, what is \\(\\cos\\theta\\)?","answer":"\\(-\\dfrac{1}{2}\\)","solution":"\\(\\cos\\theta = \\dfrac{1}{\\sec\\theta} = \\dfrac{1}{-2} = -\\dfrac{1}{2}\\)."}]);
  add("trigonometry", "tr5", 0, [{"type":"regular","q":"In triangle ABC, \\(A=35°, B=70°, a=8\\). Find \\(b\\).","answer":"\\(\\approx 14.05\\)","solution":"Use Law of Sines: \\(\\frac{a}{\\sin A} = \\frac{b}{\\sin B}\\), so \\(b = \\frac{8 \\sin 70°}{\\sin 35°}\\)."},{"type":"regular","q":"Triangle DEF: \\(D=50°, E=75°, d=12\\). Find \\(e\\).","answer":"\\(\\approx 14.68\\)","solution":"Apply Law of Sines: \\(\\frac{d}{\\sin D} = \\frac{e}{\\sin E}\\), so \\(e = \\frac{12 \\sin 75°}{\\sin 50°}\\)."},{"type":"regular","q":"In triangle PQR, \\(P=28°, Q=85°, p=6\\). Find \\(q\\).","answer":"\\(\\approx 12.73\\)","solution":"Use \\(\\frac{p}{\\sin P} = \\frac{q}{\\sin Q}\\) to get \\(q = \\frac{6 \\sin 85°}{\\sin 28°}\\)."},{"type":"regular","q":"Triangle XYZ: \\(X=55°, Y=40°, x=9\\). Find \\(z\\).","answer":"\\(\\approx 6.36\\)","solution":"First find \\(Z = 180° - 55° - 40° = 85°\\), then use Law of Sines: \\(z = \\frac{9 \\sin 85°}{\\sin 55°}\\)."},{"type":"regular","q":"In triangle ABC, \\(A=20°, C=110°, a=5\\). Find \\(c\\).","answer":"\\(\\approx 13.86\\)","solution":"Apply Law of Sines: \\(\\frac{a}{\\sin A} = \\frac{c}{\\sin C}\\), so \\(c = \\frac{5 \\sin 110°}{\\sin 20°}\\)."},{"type":"regular","q":"Triangle MNO: \\(M=65°, N=50°, m=11\\). Find \\(n\\).","answer":"\\(\\approx 9.60\\)","solution":"Use Law of Sines: \\(n = \\frac{11 \\sin 50°}{\\sin 65°}\\)."},{"type":"regular","q":"In triangle ABC, \\(B=72°, C=38°, b=7\\). Find \\(c\\).","answer":"\\(\\approx 4.88\\)","solution":"Apply Law of Sines: \\(\\frac{b}{\\sin B} = \\frac{c}{\\sin C}\\), so \\(c = \\frac{7 \\sin 38°}{\\sin 72°}\\)."},{"type":"regular","q":"Triangle with angles \\(33°\\) and \\(82°\\), side opposite \\(33°\\) is 4. Find side opposite \\(82°\\).","answer":"\\(\\approx 7.34\\)","solution":"Use Law of Sines directly: \\(\\frac{4}{\\sin 33°} = \\frac{x}{\\sin 82°}\\)."},{"type":"word","q":"A surveyor measures angle A as \\(40°\\) and angle B as \\(65°\\) in a triangle. The side opposite angle A is 150 m. Find the side opposite angle B.","answer":"\\(\\approx 206.5\\) m","solution":"Apply Law of Sines: \\(\\frac{150}{\\sin 40°} = \\frac{b}{\\sin 65°}\\)."},{"type":"word","q":"A ladder leans against a wall forming a triangle. One angle is \\(55°\\), another is \\(60°\\), and the side opposite the \\(55°\\) angle is 8 m. Find the side opposite the \\(60°\\) angle.","answer":"\\(\\approx 8.50\\) m","solution":"Use Law of Sines: \\(\\frac{8}{\\sin 55°} = \\frac{x}{\\sin 60°}\\)."},{"type":"word","q":"In a navigation problem, a ship travels in a triangle path. Angle at port A is \\(48°\\), angle at port B is \\(67°\\), and distance from A is 20 km. Find distance from B.","answer":"\\(\\approx 25.18\\) km","solution":"Apply Law of Sines: \\(\\frac{20}{\\sin 48°} = \\frac{x}{\\sin 67°}\\)."},{"type":"word","q":"A triangular plot of land has angles \\(52°\\) and \\(71°\\) at two vertices. The side opposite the \\(52°\\) angle is 120 m. Find the side opposite the \\(71°\\) angle.","answer":"\\(\\approx 147.3\\) m","solution":"Use Law of Sines: \\(\\frac{120}{\\sin 52°} = \\frac{x}{\\sin 71°}\\)."},{"type":"word","q":"A bridge spans across a triangular valley. One angle is \\(35°\\), another is \\(78°\\), and the side opposite the \\(35°\\) angle is 250 m. Find the side opposite the \\(78°\\) angle.","answer":"\\(\\approx 404.8\\) m","solution":"Apply Law of Sines: \\(\\frac{250}{\\sin 35°} = \\frac{x}{\\sin 78°}\\)."},{"type":"word","q":"A triangular garden has angles \\(42°\\) and \\(63°\\) at two corners. The side opposite the \\(42°\\) angle is 15 m. Find the side opposite the \\(63°\\) angle.","answer":"\\(\\approx 19.75\\) m","solution":"Use Law of Sines: \\(\\frac{15}{\\sin 42°} = \\frac{x}{\\sin 63°}\\)."}]);
  add("trigonometry", "tr5", 1, [{"type":"regular","q":"In triangle ABC, \\(a=4, b=6, C=45°\\). Find \\(c\\).","answer":"\\(\\approx 4.43\\)","solution":"Use Law of Cosines: \\(c^2 = 16 + 36 - 2(4)(6)\\cos 45° = 52 - 48 \\cdot \\frac{\\sqrt{2}}{2}\\)."},{"type":"regular","q":"Triangle DEF: \\(d=5, e=8, F=120°\\). Find \\(f\\).","answer":"\\(\\sqrt{129}\\) or \\(\\approx 11.36\\)","solution":"Apply Law of Cosines: \\(f^2 = 25 + 64 - 2(5)(8)\\cos 120° = 89 + 40\\)."},{"type":"regular","q":"In triangle PQR, \\(p=7, q=9, R=75°\\). Find \\(r\\).","answer":"\\(\\approx 9.88\\)","solution":"Use Law of Cosines: \\(r^2 = 49 + 81 - 2(7)(9)\\cos 75°\\)."},{"type":"regular","q":"Triangle with sides \\(a=3, b=5, c=6\\). Find \\(\\cos A\\).","answer":"\\(\\approx 0.867\\)","solution":"Rearrange Law of Cosines: \\(\\cos A = \\frac{b^2 + c^2 - a^2}{2bc} = \\frac{25 + 36 - 9}{60}\\)."},{"type":"regular","q":"In triangle ABC, \\(a=8, b=10, c=12\\). Find \\(\\cos B\\).","answer":"\\(0.65\\)","solution":"Use \\(\\cos B = \\frac{a^2 + c^2 - b^2}{2ac} = \\frac{64 + 144 - 100}{2(8)(12)}\\)."},{"type":"regular","q":"Triangle XYZ: \\(x=4, y=5, z=7\\). Find \\(\\cos Z\\).","answer":"\\(-\\frac{1}{5}\\) or \\(-0.2\\)","solution":"Apply \\(\\cos Z = \\frac{x^2 + y^2 - z^2}{2xy} = \\frac{16 + 25 - 49}{40}\\)."},{"type":"regular","q":"In triangle MNO, \\(m=6, n=8, O=55°\\). Find \\(o\\).","answer":"\\(\\approx 6.97\\)","solution":"Use Law of Cosines: \\(o^2 = 36 + 64 - 2(6)(8)\\cos 55°\\)."},{"type":"regular","q":"Triangle with sides 5, 7, 9. Find \\(\\cos C\\) (where C is opposite the side of length 9).","answer":"\\(-\\frac{1}{14}\\) or \\(\\approx -0.071\\)","solution":"Apply \\(\\cos C = \\frac{25 + 49 - 81}{2(5)(7)} = \\frac{-7}{70}\\)."},{"type":"word","q":"Two roads meet at an angle of \\(68°\\). One road is 3 km long, the other is 4 km long. How far apart are their endpoints?","answer":"\\(\\approx 4.11\\) km","solution":"Use Law of Cosines with \\(a=3, b=4, C=68°\\) to find the distance between endpoints."},{"type":"word","q":"A triangular plot of land has sides 50 m, 60 m, and 70 m. Find the angle opposite the 70 m side.","answer":"\\(\\approx 78.5°\\)","solution":"Use \\(\\cos C = \\frac{2500 + 3600 - 4900}{2(50)(60)}\\) to find the angle."},{"type":"word","q":"A triangle has sides 12 cm and 15 cm with an included angle of \\(50°\\). Find the third side.","answer":"\\(\\approx 11.70\\) cm","solution":"Apply Law of Cosines: \\(c^2 = 144 + 225 - 2(12)(15)\\cos 50°\\)."},{"type":"word","q":"Two ships leave a port at an angle of \\(42°\\) to each other. Ship A travels 20 km, Ship B travels 25 km. How far apart are they?","answer":"\\(\\approx 16.96\\) km","solution":"Use Law of Cosines: \\(d^2 = 400 + 625 - 2(20)(25)\\cos 42°\\)."},{"type":"word","q":"A triangular frame has sides 8 inches, 10 inches, and 12 inches. Find the smallest angle.","answer":"\\(\\approx 41.4°\\)","solution":"The smallest angle is opposite the shortest side; use \\(\\cos A = \\frac{100 + 144 - 64}{2(10)(12)}\\)."},{"type":"word","q":"A ladder of length 5 m leans against a wall. The base is 2 m from the wall and the wall makes an angle with the ground. If the ladder makes a triangle with the wall and ground, find the angle at the top of the ladder.","answer":"\\(\\approx 23.6°\\)","solution":"Use Law of Cosines with sides 5, 2, and \\(\\sqrt{21}\\) (height on wall)."}]);
  add("trigonometry", "tr5", 2, [{"type":"regular","q":"Find the area of triangle ABC where \\(a=6, b=9, C=40°\\).","answer":"\\(\\approx 17.36\\) square units","solution":"Use area formula \\(\\text{Area} = \\frac{1}{2}ab\\sin C = \\frac{1}{2}(6)(9)\\sin 40°\\)."},{"type":"regular","q":"Triangle DEF has sides \\(d=7, e=10, F=55°\\). Find its area.","answer":"\\(\\approx 28.67\\) square units","solution":"Apply \\(\\text{Area} = \\frac{1}{2}de\\sin F = \\frac{1}{2}(7)(10)\\sin 55°\\)."},{"type":"regular","q":"In triangle PQR, \\(p=5, q=12, R=75°\\). Find the area.","answer":"\\(\\approx 29.04\\) square units","solution":"Use \\(\\text{Area} = \\frac{1}{2}pq\\sin R = \\frac{1}{2}(5)(12)\\sin 75°\\)."},{"type":"regular","q":"Triangle with sides 8 and 11 and included angle \\(65°\\). Find the area.","answer":"\\(\\approx 39.95\\) square units","solution":"Apply \\(\\text{Area} = \\frac{1}{2}(8)(11)\\sin 65°\\)."},{"type":"regular","q":"Find the area of a triangle with sides 5, 5, and 8 using Heron's formula.","answer":"\\(12\\) square units","solution":"Use \\(s = 9\\), then \\(\\text{Area} = \\sqrt{9 \\cdot 4 \\cdot 4 \\cdot 1} = 12\\)."},{"type":"regular","q":"Triangle with sides 7, 10, and 13. Find the area using Heron's formula.","answer":"\\(\\approx 34.12\\) square units","solution":"Calculate \\(s = 15\\), then \\(\\text{Area} = \\sqrt{15 \\cdot 8 \\cdot 5 \\cdot 2}\\)."},{"type":"regular","q":"Find the area of an equilateral triangle with side length 10.","answer":"\\(25\\sqrt{3}\\) or \\(\\approx 43.30\\) square units","solution":"Use \\(\\text{Area} = \\frac{s^2\\sqrt{3}}{4} = \\frac{100\\sqrt{3}}{4}\\)."},{"type":"regular","q":"Triangle XYZ has sides 9, 12, and 15. Find its area.","answer":"\\(54\\) square units","solution":"Recognize this is a 3-4-5 right triangle scaled by 3; use \\(\\text{Area} = \\frac{1}{2}(9)(12)\\)."},{"type":"word","q":"A triangular garden has two sides of 12 m and 15 m with an included angle of \\(50°\\). What is its area?","answer":"\\(\\approx 68.82\\) square meters","solution":"Use \\(\\text{Area} = \\frac{1}{2}(12)(15)\\sin 50°\\)."},{"type":"word","q":"A triangular roof section has sides 20 ft, 25 ft, and 30 ft. Find its area.","answer":"\\(\\approx 290.47\\) square feet","solution":"Use Heron's formula with \\(s = 37.5\\)."},{"type":"word","q":"A triangular park has two sides of 80 m and 100 m meeting at an angle of \\(48°\\). What is its area?","answer":"\\(\\approx 2973.1\\) square meters","solution":"Apply \\(\\text{Area} = \\frac{1}{2}(80)(100)\\sin 48°\\)."},{"type":"word","q":"A triangular sail has sides 8 m, 10 m, and 12 m. What is its area?","answer":"\\(\\approx 39.69\\) square meters","solution":"Use Heron's formula with \\(s = 15\\)."},{"type":"word","q":"A triangular field has two sides of 50 m and 60 m with an included angle of \\(62°\\). Find its area.","answer":"\\(\\approx 1326.5\\) square meters","solution":"Use \\(\\text{Area} = \\frac{1}{2}(50)(60)\\sin 62°\\)."},{"type":"word","q":"A triangle has sides 13, 14, and 15. Find its area using Heron's formula.","answer":"\\(84\\) square units","solution":"Calculate \\(s = 21\\), then \\(\\text{Area} = \\sqrt{21 \\cdot 8 \\cdot 7 \\cdot 6} = 84\\)."},{"type":"word","q":"A triangular billboard has two sides of 6 m and 8 m with an included angle of \\(90°\\). What is its area?","answer":"\\(24\\) square meters","solution":"Use \\(\\text{Area} = \\frac{1}{2}(6)(8)\\sin 90° = 24\\)."}]);
  addCum("trigonometry", "tr5", [{"type":"regular","q":"State the Law of Sines formula.","answer":"\\(\\frac{a}{\\sin A} = \\frac{b}{\\sin B} = \\frac{c}{\\sin C}\\)","solution":"The Law of Sines relates the sides of a triangle to the sines of their opposite angles."},{"type":"regular","q":"State the Law of Cosines formula for side \\(a\\).","answer":"\\(a^2 = b^2 + c^2 - 2bc\\cos A\\)","solution":"The Law of Cosines relates all three sides and one angle of a triangle."},{"type":"regular","q":"In triangle ABC, \\(A=25°, B=80°, a=6\\). Find \\(b\\).","answer":"\\(\\approx 13.97\\)","solution":"Use Law of Sines: \\(b = \\frac{6 \\sin 80°}{\\sin 25°}\\)."},{"type":"regular","q":"Triangle with sides \\(a=5, b=7, C=50°\\). Find \\(c\\).","answer":"\\(\\approx 5.45\\)","solution":"Apply Law of Cosines: \\(c^2 = 25 + 49 - 2(5)(7)\\cos 50°\\)."},{"type":"regular","q":"Find the area of a triangle with \\(a=10, b=12, C=35°\\).","answer":"\\(\\approx 34.41\\) square units","solution":"Use \\(\\text{Area} = \\frac{1}{2}ab\\sin C = \\frac{1}{2}(10)(12)\\sin 35°\\)."},{"type":"regular","q":"Triangle with sides 6, 8, 10. Is it a right triangle?","answer":"Yes","solution":"Check if \\(6^2 + 8^2 = 10^2\\); \\(36 + 64 = 100\\) is true."},{"type":"regular","q":"In triangle ABC, \\(a=4, b=5, c=6\\). Find \\(\\cos B\\).","answer":"\\(\\frac{27}{40}\\) or \\(0.675\\)","solution":"Use \\(\\cos B = \\frac{a^2 + c^2 - b^2}{2ac} = \\frac{16 + 36 - 25}{48}\\)."},{"type":"regular","q":"Find the area of a triangle with sides 9, 12, 15 using Heron's formula.","answer":"\\(54\\) square units","solution":"This is a 3-4-5 right triangle scaled by 3; area is \\(\\frac{1}{2}(9)(12)\\)."},{"type":"regular","q":"Triangle with angles \\(30°\\) and \\(70°\\), side opposite \\(30°\\) is 5. Find side opposite \\(70°\\).","answer":"\\(\\approx 9.24\\)","solution":"Use Law of Sines: \\(\\frac{5}{\\sin 30°} = \\frac{x}{\\sin 70°}\\)."},{"type":"regular","q":"In triangle PQR, \\(p=8, q=11, R=60°\\). Find \\(r\\).","answer":"\\(\\approx 9.85\\)","solution":"Apply Law of Cosines: \\(r^2 = 64 + 121 - 2(8)(11)\\cos 60°\\)."},{"type":"word","q":"A surveyor measures a triangular plot with angles \\(45°\\) and \\(65°\\) at two vertices. The side opposite the \\(45°\\) angle is 100 m. Find the side opposite the \\(65°\\) angle.","answer":"\\(\\approx 129.4\\) m","solution":"Use Law of Sines: \\(\\frac{100}{\\sin 45°} = \\frac{x}{\\sin 65°}\\)."},{"type":"word","q":"Two roads meet at an angle of \\(55°\\). One road is 2.5 km, the other is 3 km. How far apart are their endpoints?","answer":"\\(\\approx 2.60\\) km","solution":"Use Law of Cosines: \\(d^2 = 2.5^2 + 3^2 - 2(2.5)(3)\\cos 55°\\)."},{"type":"word","q":"A triangular piece of land has sides 40 m, 50 m, and 60 m. Find the angle opposite the 60 m side.","answer":"\\(\\approx 82.8°\\)","solution":"Use \\(\\cos C = \\frac{1600 + 2500 - 3600}{2(40)(50)}\\)."},{"type":"word","q":"A triangular garden has two sides of 25 m and 30 m with an included angle of \\(58°\\). What is its area?","answer":"\\(\\approx 318.3\\) square meters","solution":"Use \\(\\text{Area} = \\frac{1}{2}(25)(30)\\sin 58°\\)."},{"type":"word","q":"A navigation triangle has vertices A, B, C. Angle A is \\(38°\\), angle B is \\(72°\\), and side AB is 15 km. Find side BC.","answer":"\\(\\approx 9.93\\) km","solution":"Angle C is \\(70°\\); use Law of Sines: \\(\\frac{15}{\\sin 70°} = \\frac{BC}{\\sin 38°}\\)."},{"type":"word","q":"A triangular roof has sides 18 ft, 24 ft, and 30 ft. Find its area.","answer":"\\(216\\) square feet","solution":"This is a 3-4-5 right triangle scaled by 6; area is \\(\\frac{1}{2}(18)(24)\\)."},{"type":"word","q":"Two ships depart from a port at an angle of \\(52°\\) to each other. Ship A travels 18 km, Ship B travels 22 km. How far apart are they?","answer":"\\(\\approx 17.63\\) km","solution":"Use Law of Cosines: \\(d^2 = 324 + 484 - 2(18)(22)\\cos 52°\\)."},{"type":"word","q":"A triangular plot has sides 11 m, 13 m, and 20 m. Find its area using Heron's formula.","answer":"\\(\\approx 71.45\\) square meters","solution":"Calculate \\(s = 22\\), then \\(\\text{Area} = \\sqrt{22 \\cdot 11 \\cdot 9 \\cdot 2}\\)."},{"type":"word","q":"A ladder forms a triangle with a wall and the ground. The ladder is 6 m long, the base is 2.5 m from the wall. Find the angle the ladder makes with the ground.","answer":"\\(\\approx 65.4°\\)","solution":"Height on wall is \\(\\sqrt{36 - 6.25} \\approx 5.45\\) m; use \\(\\cos \\theta = \\frac{2.5}{6}\\)."},{"type":"word","q":"A triangular banner has two sides of 7 ft and 9 ft with an included angle of \\(72°\\). What is its area?","answer":"\\(\\approx 30.07\\) square feet","solution":"Use \\(\\text{Area} = \\frac{1}{2}(7)(9)\\sin 72°\\)."},{"type":"word","q":"A triangle has sides 16, 17, and 18. Find its area using Heron's formula.","answer":"\\(\\approx 140.4\\) square units","solution":"Calculate \\(s = 25.5\\), then \\(\\text{Area} = \\sqrt{25.5 \\cdot 9.5 \\cdot 8.5 \\cdot 7.5}\\)."},{"type":"word","q":"In a surveying problem, angle A is \\(32°\\), angle C is \\(88°\\), and side AC is 200 m. Find side AB.","answer":"\\(\\approx 106.4\\) m","solution":"Angle B is \\(60°\\); use Law of Sines: \\(\\frac{200}{\\sin 60°} = \\frac{AB}{\\sin 88°}\\)."}]);
